const $ = (s, root=document) => root.querySelector(s);
const escape = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pre = v => `<pre>${escape(typeof v === 'string' ? v : JSON.stringify(v,null,2))}</pre>`;
const operations=['catalog','show','lookup','check','demand','answers'];
const labels={catalog:'Browse the catalog',show:'Open an entry',lookup:'Look up a proof',check:'Run a check',demand:'Review demand',answers:'Review answers'};
let count=0;
const cells=[];
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:r.status,data:await r.json()};}
function evidence(e){return `<div class="${e.replay.status==='recorded'?'warning':'result'}">${e.replay.status==='recorded'?'Recorded stub — not re-run by fvapi':'Replay available — re-check locally'}</div><h2>${escape(e.title)}</h2><p>${escape(e.claim)}</p><div class="metadata"><span>${escape(e.id)}</span><span>${escape(e.kind)}</span><span>${escape(e.toolchain)}</span></div><h3>Read the exact statement</h3>${e.statements.map(s=>`<small>${escape(s.file)}:${s.line} / ${escape(s.name)}</small>${pre(s.text)}`).join('')}<h3>Delivered proof files</h3>${e.closure.map(f=>`<p>${escape(f.path)} <small>${f.bytes} bytes</small></p>${pre(f.sha256)}`).join('')}<h3>Replay in your environment</h3><button data-copy="${escape(e.replay.command)}">Copy replay command</button>${pre(e.replay.command)}<p>${escape(e.replay.note)}</p>${e.replay.transcript?pre(e.replay.transcript):''}<h3>Expected axioms</h3>${pre(e.replay.expect_axioms)}<h3>Licence and notices</h3><p>${escape(e.licence.spdx)}</p>${e.licence.third_party.length?pre(e.licence.third_party):'<p>No third-party notices listed.</p>'}<h3>Source</h3>${pre(e.source)}<p>Dependencies: ${escape(e.requires.join(', '))}</p><a class="bundle" href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download proof bundle</a>`;}
function add(op,input,note,state){const id=++count;const cell={id,op,state:state||'cell-'+id};cells.push(cell);const article=document.createElement('article');article.className='cell';article.id=cell.state;article.innerHTML=`<span class="prompt">In [${id}]</span><div class="request"><div class="cellbar"><label for="op-${id}">Request</label><select id="op-${id}">${operations.map(o=>`<option value="${o}" ${o===op?'selected':''}>${labels[o]}</option>`).join('')}</select><span class="spacer"></span><button data-run>Run cell</button><button data-up aria-label="Move cell up">↑</button><button data-down aria-label="Move cell down">↓</button></div><textarea aria-label="Request input for cell ${id}" spellcheck="false" rows="${op==='check'?8:op==='lookup'?3:1}">${escape(typeof input==='object'?JSON.stringify(input,null,2):input||'')}</textarea></div><p class="cellnote">${escape(note||'Edit this request, then run the cell.')}</p><div class="output" aria-live="polite"></div>`;
$('#notebook').append(article);cell.el=article;
$('select',article).onchange=ev=>{cell.op=ev.target.value;$('textarea',article).value=['demand','answers','catalog'].includes(cell.op)?'':cell.op==='lookup'?'{"spec_id":"vf.contrast-2x2"}':cell.op==='show'?'vf.contrast-2x2':'{"entry_id":"vf.contrast-2x2","input":{}}';};
$('[data-run]',article).onclick=()=>run(cell);
$('[data-up]',article).onclick=()=>{const p=article.previousElementSibling;if(p)article.parentNode.insertBefore(article,p);};
$('[data-down]',article).onclick=()=>{const n=article.nextElementSibling;if(n)article.parentNode.insertBefore(n,article);};
return cell;}
async function run(cell){const out=$('.output',cell.el),button=$('[data-run]',cell.el);button.disabled=true;out.innerHTML='<small>Running request…</small>';try{const text=$('textarea',cell.el).value.trim();let path=cell.op,body;
if(cell.op==='show')path='catalog/'+encodeURIComponent(text);if(cell.op==='lookup')body=JSON.parse(text);if(cell.op==='check'){const v=JSON.parse(text);path='checks/'+encodeURIComponent(v.entry_id);body=v.input;}
const {status,data}=await api(path,body);let html=`<small>Out [${cell.id}] &nbsp; HTTP ${status}</small>`;
if(status>=400){html+=`<p class="warning">${status===404&&cell.op==='lookup'?'No matching proof. Logged as demand.':status===409?'This entry has no runnable checker. Choose a checker entry.':'The request could not complete. Check the input and try again.'}</p>${pre(data)}`;}
else if(cell.op==='catalog'){html+=`<h2>${data.entries.length} library entries</h2><table class="catalog"><thead><tr><th>Entry / claim</th><th>Kind</th><th>Replay</th></tr></thead><tbody>${data.entries.map(e=>`<tr><td><button data-entry="${escape(e.id)}">${escape(e.title)}</button><small>${escape(e.id)}</small><small>${escape(e.claim)}</small></td><td>${escape(e.kind)}</td><td class="${e.replay_status==='recorded'?'tag':''}">${e.replay_status==='recorded'?'Recorded stub':'Real replay'}</td></tr>`).join('')}</tbody></table><p class="cellnote">Recorded stubs were not re-run by fvapi. Open an entry to inspect its evidence.</p>`;}
else if(cell.op==='show')html+=evidence(data);
else if(cell.op==='lookup'){html+='<p class="result">Match found. Inspect the proof before you use it.</p>'+evidence(data.entry);}
else if(cell.op==='check'){html+=`<h2 class="${data.verdict==='accept'?'result':'warning'}">${data.verdict==='accept'?'✓ Accepted by the checker':'× Rejected by the checker'}</h2><p>${data.verdict==='accept'?'The server accepted this input. Re-check it locally.':'The input does not match the proved weights. Edit the weights and run the cell again.'}</p><div class="metadata"><span>${escape(data.ran_on)}</span><span>${data.elapsed_ms} ms</span><span>Exit code ${data.exit_code}</span></div>${pre(data.output)}<h3>Re-check locally</h3>${pre(data.recheck.command)}<a href="${escape(data.recheck.bundle)}">Download checker bundle</a>`;}
else if(cell.op==='demand'){html+='<h2>Unanswered requests</h2><h3>Counts by query key</h3>'+pre(data.by_key)+'<h3>Misses, newest first</h3>'+pre(data.misses);}
else html+='<h2>Answer log</h2>'+pre(data);
out.innerHTML=html;out.querySelectorAll('[data-entry]').forEach(b=>b.onclick=async()=>{const next=add('show',b.dataset.entry,'Opened from the catalog.');await run(next);next.el.scrollIntoView();});out.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';}catch{b.textContent='Select the command below to copy it';}});
}catch(e){out.innerHTML=`<p class="warning">The request did not run. Check that the input is valid JSON and the API is available.</p>${pre(e.message)}`;}finally{button.disabled=false;}}
async function runAll(){const b=$('#run-all');b.disabled=true;$('#status').textContent='Running notebook…';for(const el of $('#notebook').children){const c=cells.find(c=>c.el===el);if(c)await run(c);}b.disabled=false;$('#status').textContent='All cells finished';}
async function init(){try{const {data:entry}=await api('catalog/vf.contrast-2x2');const good=entry.check.example_input;const bad=structuredClone(good);bad.rows[0].weights[0]+=1;
add('catalog','','Start with the library. Open any entry to append an evidence cell.','catalog');add('show',entry.id,'Read the statement, not just the title.','entry');add('lookup',{spec_id:entry.id},'A known specification returns its proof package.','lookup-hit');add('check',{entry_id:entry.id,input:good},'Run the supplied example. The request is editable.','check-accept');add('check',{entry_id:entry.id,input:bad},'One weight is changed. The checker must reject it.','check-reject');add('lookup',{spec_id:'example.unanswered'},'A miss becomes demand, not an agent request.','lookup-miss');add('demand','','Inspect the requests that the library cannot yet answer.','demand');add('answers','','Inspect the history of returned answers.','answers');add('show','fva.glm-iround','A recorded transcript is not a fresh replay.','recorded');add('check',{entry_id:'fva.glm-iround',input:{}},'A proof entry does not necessarily provide an input checker.','check-409');
$('#outline').innerHTML=cells.map(c=>`<a href="#${c.state}">${labels[c.op]}${c.state==='check-reject'?' (edited)':''}</a>`).join('');$('#outline').onclick=async ev=>{const a=ev.target.closest('a');if(!a)return;const c=cells.find(c=>'#'+c.state===a.getAttribute('href'));if(c){c.el.hidden=false;if(!$('.output',c.el).textContent)await run(c);c.el.scrollIntoView();}};$('#run-all').onclick=runAll;$('#add').onclick=()=>{const c=add('lookup',{spec_id:entry.id});c.el.scrollIntoView();$('textarea',c.el).focus();};
const state=new URLSearchParams(location.search).get('state');if(state&&state!=='mobile'){cells.forEach(c=>c.el.hidden=c.state!==state);$('#status').innerHTML='<a href="?">Show the full notebook</a>';const c=cells.find(c=>c.state===state);if(c)await run(c);}else await runAll();document.body.dataset.ready='true';
}catch(e){$('#status').textContent='The API is unavailable. Reload to try again.';document.body.dataset.ready='error';}}
init();
